CREATE TABLE mp3_document(id INTEGER PRIMARY KEY CHECK(id=1),schema TEXT NOT NULL);
CREATE TABLE mp3_id3v2_tag(id INTEGER PRIMARY KEY REFERENCES mp3_document(id) CHECK(id=1));
CREATE TABLE mp3_id3v2_frame(id INTEGER PRIMARY KEY,tag_id INTEGER NOT NULL REFERENCES mp3_id3v2_tag(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),frame_identifier TEXT NOT NULL,content_kind TEXT NOT NULL,language TEXT,description TEXT,text TEXT,url TEXT,mime TEXT,picture_type INTEGER CHECK(picture_type BETWEEN 0 AND 20));
CREATE TABLE mp3_id3_text_value(id INTEGER PRIMARY KEY,frame_id INTEGER NOT NULL REFERENCES mp3_id3v2_frame(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),value TEXT NOT NULL);
CREATE TABLE mp3_id3_content_octet(id INTEGER PRIMARY KEY,frame_id INTEGER NOT NULL REFERENCES mp3_id3v2_frame(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),octet INTEGER NOT NULL CHECK(octet BETWEEN 0 AND 255));
CREATE TABLE mp3_id3v1_tag(id INTEGER PRIMARY KEY REFERENCES mp3_document(id) CHECK(id=1),title TEXT NOT NULL,artist TEXT NOT NULL,album TEXT NOT NULL,year TEXT NOT NULL,comment TEXT NOT NULL,track INTEGER CHECK(track BETWEEN 1 AND 255),genre INTEGER CHECK(genre BETWEEN 0 AND 254));
CREATE TABLE mp3_audio_frame(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES mp3_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),mpeg_version_id INTEGER NOT NULL CHECK(mpeg_version_id BETWEEN 0 AND 255),layer INTEGER NOT NULL CHECK(layer BETWEEN 0 AND 255),protection_bit INTEGER NOT NULL CHECK(protection_bit IN(0,1)),bitrate_index INTEGER NOT NULL CHECK(bitrate_index BETWEEN 0 AND 255),sample_rate_index INTEGER NOT NULL CHECK(sample_rate_index BETWEEN 0 AND 255),padding INTEGER NOT NULL CHECK(padding IN(0,1)),private_bit INTEGER NOT NULL CHECK(private_bit IN(0,1)),channel_mode INTEGER NOT NULL CHECK(channel_mode BETWEEN 0 AND 255),mode_extension INTEGER NOT NULL CHECK(mode_extension BETWEEN 0 AND 255),copyright INTEGER NOT NULL CHECK(copyright IN(0,1)),original INTEGER NOT NULL CHECK(original IN(0,1)),emphasis INTEGER NOT NULL CHECK(emphasis BETWEEN 0 AND 255));
CREATE TABLE mp3_audio_payload_octet(id INTEGER PRIMARY KEY,frame_id INTEGER NOT NULL REFERENCES mp3_audio_frame(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),octet INTEGER NOT NULL CHECK(octet BETWEEN 0 AND 255));
